import pathlib
import re

HERE = pathlib.Path(__file__).resolve().parent
# 시각, 레벨, [모듈], 메시지
LINE_RE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+ERROR\s+\[([^\]]+)\]\s*(.*)$")


def parse_errors(path):
    # ERROR 줄만 (시각, 모듈, 메시지)로 추출
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append(m.groups())
    return rows


def escape_cell(text):
    # 표 구분자와 겹치는 파이프 이스케이프
    return text.replace("|", "\\|")


def build_table(rows):
    lines = ["| 시각 | 모듈 | 메시지 |", "| --- | --- | --- |"]
    for row in rows:
        lines.append("| " + " | ".join(escape_cell(c) for c in row) + " |")
    return "\n".join(lines) + "\n"


def main():
    rows = parse_errors(HERE / "sample.log")
    with open(HERE / "errors.md", "w", encoding="utf-8", newline="\n") as f:
        f.write(build_table(rows))


if __name__ == "__main__":
    main()

